const all = await items.list();
return {
 jira: j.map(i => i.gone ? i : ({id:i.id, type:i.issueType, s:i.summary, st:i.status.name, a:i.assignee?.name ?? null, p:i.points, d:i.description.slice(0,200), c:i.comments.slice(-1).map(c=>c.body.slice(0,150))})),
 files: all.filter(i => i.id.startsWith("folder:")).map(i => i.gone ? i : ({title:i.title, t:i.text.slice(0,300)}))
};

